2	
3	import net.minecraft.util.math.Vec3d;
4	
5	import java.util.ArrayList;
6	import java.util.List;
7	import java.util.Locale;
8	
9	/**
10	 * Formats the K-key "kapture" log lines for a focused ray's captured bounces: one header line,
11	 * one line per bounce, and one footer line. Pure formatting — no logging side effects, no
12	 * Minecraft-client imports beyond {@link Vec3d} (already a plain-data type used by
13	 * {@link CaptureBuffer.CapturedRay}).
14	 */
15	final class KaptureLogger {
16	
17		private KaptureLogger() {}
18	
19		/**
20		 * @param rayIndex the env-eval ray index the bounces belong to (all elements of {@code bounces}
21		 *     are expected to share this index; only used for header/footer text here)
22		 * @param bounces non-empty list of captured bounces for {@code rayIndex}, in bounce order
23		 * @return header line, one line per bounce, footer line — in that order
24		 */
25		static List<String> formatLines(int rayIndex, List<CaptureBuffer.CapturedRay> bounces) {
26			List<String> lines = new ArrayList<>(bounces.size() + 2);
27			int soundEventId = bounces.get(0).soundEventId();
28			lines.add(String.format(Locale.ROOT,
29					"Resounding KAPTURE ray #%d sound=%d bounces=%d ---",
30					rayIndex, soundEventId, bounces.size()));
31			for (CaptureBuffer.CapturedRay bounce : bounces) {
32				lines.add(formatBounceLine(bounce));
33			}
34			lines.add(String.format(Locale.ROOT, "Resounding KAPTURE ray #%d --- end", rayIndex));
35			return lines;
36		}
37	
38		private static String formatBounceLine(CaptureBuffer.CapturedRay bounce) {
39			StringBuilder sb = new StringBuilder();
40			sb.append(String.format(Locale.ROOT,
41					"Resounding KAPTURE: ray #%d bounce #%d node=%d\u00b3 mode=%s start=%s end=%s "
42							+ "material=%s Zprev=%.1f Z=%.1f R=%.3f T=%.3f power=%.1f polar=%.3f%s frustum=%.2f",
43					bounce.rayIndex(),
44					bounce.bounceIndex(),
45					bounce.branchSize(),
46					bounce.shapeMode() ? "SHAPE" : "VOXEL",
47					formatPos(bounce.start()),
48					formatPos(bounce.end()),
49					bounce.materialLabel() == null ? "?" : bounce.materialLabel(),
50					bounce.priorImpedance(),
51					bounce.resolvedImpedance(),
52					bounce.reflectivity(),
53					bounce.transmission(),
54					bounce.power(),
55					bounce.polarAlignment(),
56					// polarAlignment defaults to 1.0 for both "fully aligned" and "no polarity at
57					// all" -- disambiguate explicitly instead of leaving both print identically.
58					bounce.hasPolarity() ? "" : "/none",
59					bounce.frustumSize()
60			));
61			String growth = growthTag(bounce);
62			if (growth != null) {
63				sb.append(" growth=").append(growth);
64			}
65			if (bounce.blankReason() != null) {
66				sb.append(" blank=").append(bounce.blankReason());
67			}
68			if (bounce.terminated()) {
69				sb.append(" TERMINATED");
70			}
71			return sb.toString();
72		}
73	
74		/** {@code null} when none of the growth-affecting flags fired this bounce. */
75		private static String growthTag(CaptureBuffer.CapturedRay bounce) {
76			if (bounce.peekReflect()) {
77				return "peek";
78			}
79			if (bounce.freeRefraction()) {
80				return "free";
81			}
82			if (bounce.growthDeferred()) {
83				return "deferred";
84			}
85			return null;
86		}
87	
88		/** Mirrors {@code Engine.formatPos}'s style (4-decimal, comma-separated, locale-independent). */
89		private static String formatPos(Vec3d pos) {
90			return String.format(Locale.ROOT, "%.4f,%.4f,%.4f", pos.x, pos.y, pos.z);
91		}
92	}
