44			@Nullable String materialLabel = cast.lastMaterialLabel;
45	
46			DebugRenderDispatcher.INSTANCE.bounceRays().addSoundBounceRay(
47					start, end, color, bounceIndex, sourceID, rayIndex, material, reflectivity, transmission,
48					power, branchSize, terminated, cause
49			);
50			if (CaptureBuffer.INSTANCE.isCapturing()) {
51				int capturedColor = terminated ? (cause != null ? cause.color : BounceRayLayer.TERMINATED_COLOR) : color;
52				double resolvedImpedance = cast.lastResolvedImpedance;
53				double polarAlignment = cast.lastPolarAlignment;
54				double frustumSize = cast.frustumSize;
