61						sourceID, rayIndex, bounceIndex, material, reflectivity, transmission, power,
62						priorImpedance, branchSize, materialLabel, terminated,
63						resolvedImpedance, polarAlignment, frustumSize, blankReason, shapeMode,
64						cast.lastHasPolarity, cast.lastGrowthDeferred, cast.lastFreeRefraction, cast.lastPeekReflect
65				));
