48	     * Blended "effective ray norm": {@code normalize(rayNorm + normalize(octantCenter -
49	     * incidentPoint))}. Falls back to {@code normalize(rayNorm)} when either the offset or the
50	     * sum is degenerate.
51	     */
52	    public static Vec3d dualDerivedNorm(@NotNull Vec3d rayNorm, @NotNull Vec3d incidentPoint, @NotNull Vec3d octantCenter) {
53	        Vec3d rn = rayNorm.normalize();
54	        Vec3d offset = octantCenter.subtract(incidentPoint);
55	        if (offset.lengthSquared() < 1e-12) {
56	            return rn;
57	        }
58	        Vec3d offsetNorm = offset.normalize();
59	        Vec3d sum = rn.add(offsetNorm);
60	        if (sum.lengthSquared() < 1e-12) {
61	            return rn;
62	        }
63	        return sum.normalize();
64	    }
