90	    /**
91	     * Permeation sign-copy bending (frustums-plan.md "Which vector to copy against — resolved,
92	     * replaces the earlier hard cutoff with a smooth lerp"): given the raw incident vector
93	     * {@code ray} (its magnitude is preserved verbatim, only signs may change), its normalized
94	     * direction {@code rayNorm}, and the octant's {@code polNorm}, computes
95	     * {@code dot = polNorm·rayNorm}, {@code similarity = |dot|*dot}, {@code tangent = rayNorm -
96	     * dot*polNorm}, {@code t = clamp(similarity, 0, 1)}, {@code target = lerp(tangent, polNorm,
97	     * t)}, then copies {@code target}'s per-component sign onto {@code ray}'s per-component
98	     * magnitude. {@code |result| == |ray|} always (only sign bits change). Not yet implemented
99	     * &mdash; always throws.
100	     */
101	    public static @NotNull Vec3d permeationBend(@NotNull Vec3d ray, @NotNull Vec3d rayNorm, @NotNull Vec3d polNorm) {
102	        double dot = polNorm.dotProduct(rayNorm);
103	        double similarity = Math.abs(dot) * dot;
104	        Vec3d tangent = rayNorm.subtract(polNorm.multiply(dot));
105	        double t = Math.max(0.0, Math.min(1.0, similarity));
106	        Vec3d target = tangent.multiply(1 - t).add(polNorm.multiply(t));
107	        return new Vec3d(
108	                Math.copySign(ray.x, target.x),
109	                Math.copySign(ray.y, target.y),
110	                Math.copySign(ray.z, target.z)
111	        );
112	    }
