114	    /**
115	     * Free graze-refraction bend toward the open half when frustum growth would double-cover past
116	     * the polarity plane. Partial flip damped by plain {@link #polarAlignment} (not dual-derived).
117	     * Magnitude of {@code ray} is preserved.
118	     */
119	    public static @NotNull Vec3d grazeBend(@NotNull Vec3d ray, @NotNull Vec3d rayNorm, @NotNull Vec3d polNorm) {
120	        double n = polNorm.dotProduct(rayNorm);
121	        if (n <= 0) {
122	            return ray; // already heading away from solid
123	        }
124	        double align = polarAlignment(rayNorm, polNorm);
125	        Vec3d tangent = rayNorm.subtract(polNorm.multiply(n));
126	        Vec3d bent = tangent.subtract(polNorm.multiply(n * (1.0 - align)));
127	        return bent.normalize().multiply(ray.length());
128	    }
