641	    private static double polarContrast(Branch.NodeDescriptor descriptor) {
642	        double most = descriptor.mostCommonImpedance();
643	        double least = descriptor.leastCommonImpedance();
644	        double denom = Math.max(Math.abs(most), Math.abs(least));
645	        if (denom < 1e-9 || Double.isNaN(denom)) {
646	            return 0.0;
647	        }
648	        return Math.abs(most - least) / denom;
