181	    public static Branch growOctree(WorldChunk chunk, Branch root) {
182	        final BlockPos start = root.start;
183	        if (root.size == 1) {
184	            BlockState state = chunk.getBlockState(start);
185	            root.material = MaterialRegistry.material(state);
186	            // materialLabel filled lazily by overlay / dRays via Branch.ensureMaterialLabel
187	            bakeLeafDescriptor(root);
188	            return root;
189	        }
190	
191	        final int scale = root.size >> 1;
192	        BlockState corner = chunk.getBlockState(start);
193	        root.material = MaterialRegistry.material(corner);
194	        boolean valid = true;
195	
196	        if (scale > 1) {
197	            boolean heterogeneous = false;
198	            Material siblingMaterial = null;
199	            Branch[] children = new Branch[blockSequence.length];
200	            for (int i = 0; i < blockSequence.length; i++) {
201	                final BlockPos block = blockSequence[i];
202	                final BlockPos position = start.add(block.multiply(scale));
203	                Branch leaf = growOctree(chunk, new Branch(position, scale, (Material) null));
204	                children[i] = leaf;
205	                if (leaf.material == null || !leaf.isEmpty()) {
206	                    heterogeneous = true;
207	                    valid = false;
208	                } else if (!sameAcousticCell(corner, chunk.getBlockState(position))) {
209	                    heterogeneous = true;
210	                    valid = false;
211	                } else if (siblingMaterial == null) {
212	                    siblingMaterial = leaf.material;
213	                } else if (!siblingMaterial.equals(leaf.material)) {
214	                    heterogeneous = true;
215	                    valid = false;
216	                }
217	                root.put(i, leaf);
218	            }
219	            if (!heterogeneous) {
220	                root.empty();
221	            }
222	            bakeAggregateDescriptor(root, children);
223	        } else {
224	            Material[] cornerMaterials = new Material[blockSequence.length];
225	            for (int i = 0; i < blockSequence.length; i++) {
226	                final BlockPos position = start.add(blockSequence[i]);
227	                cornerMaterials[i] = MaterialRegistry.material(chunk.getBlockState(position));
228	            }
229	            valid = regionHomogeneous(chunk, start, 2, corner);
230	            Polarization.Descriptor descriptor = Polarization.bakeOctant(cornerMaterials);
231	            root.bake(new Branch.NodeDescriptor(
232	                    descriptor.mostCommonImpedance(),
233	                    descriptor.leastCommonImpedance(),
234	                    descriptor.avgImpedance(),
235	                    descriptor.blendCoefficient(),
236	                    descriptor.polar()
237	            ));
238	            if (!valid) {
239	                root.empty();
240	                for (int i = 0; i < blockSequence.length; i++) {
241	                    final BlockPos position = start.add(blockSequence[i]);
242	                    Branch leaf = new Branch(position, 1, cornerMaterials[i]);
243	                    bakeLeafDescriptor(leaf);
244	                    root.put(i, leaf);
245	                }
246	                root.material = null;
247	                return root;
248	            }
249	        }
250	        root.set(valid ? root.material : (Material) null);
251	        return root;
252	    }
