260	    /**
261	     * Size&gt;2 baked-descriptor aggregation (frustums-plan.md Phase 0 table): high/low/avg are
262	     * the mean of the 8 children's own already-reduced high/low/avg values (one running pass, not
263	     * a second traversal); {@code polar} is the weighted average of the children's own {@code
264	     * polar} vectors, weighted by each child's own stiffness (how high-impedance-dominant that
265	     * child is, derived from its retained {@link Branch#blendCoefficient} and quantized to
266	     * quarters via {@link Polarization#stiffWeight}). Children with no gradient of their own
267	     * ({@code polar == null}) contribute no direction.
268	     */
269	    private static void bakeAggregateDescriptor(Branch root, Branch[] children) {
270	        double sumHigh = 0.0;
271	        double sumLow = 0.0;
272	        double sumAvg = 0.0;
273	        double sumBlend = 0.0;
274	        int blendCount = 0;
275	        List<Vec3d> childPolar = new ArrayList<>(children.length);
276	        List<Double> childWeight = new ArrayList<>(children.length);
277	        for (Branch child : children) {
278	            // Snapshot once: child.descriptor is a single volatile read, so every field below
279	            // comes from the same baked generation instead of possibly straddling two.
280	            Branch.NodeDescriptor d = child.descriptor;
281	            sumHigh += d.mostCommonImpedance();
282	            sumLow += d.leastCommonImpedance();
283	            sumAvg += d.avgImpedance();
284	            if (d.polar() != null) {
285	                double blend = d.blendCoefficient();
286	                if (Double.isNaN(blend)) {
287	                    double range = Math.abs(d.mostCommonImpedance() - d.leastCommonImpedance());
288	                    blend = range > 0
289	                            ? Math.abs(d.avgImpedance() - d.leastCommonImpedance()) / range
290	                            : 1.0;
291	                    blend = Math.max(0.0, Math.min(1.0, blend));
292	                }
293	                childPolar.add(d.polar());
294	                childWeight.add(Polarization.stiffWeight(blend));
295	                sumBlend += blend;
296	                blendCount++;
297	            }
298	        }
299	        Vec3d combinedPolar;
300	        if (childPolar.isEmpty()) {
301	            combinedPolar = null;
302	        } else {
303	            double[] weights = new double[childWeight.size()];
304	            for (int i = 0; i < weights.length; i++) {
305	                weights[i] = childWeight.get(i);
