180	    /** Most-common material; presence ties broken toward the stiffer (higher-impedance) material. */
181	    private static @NotNull Material selectMostCommon(@NotNull Material[] corners) {
182	        Map<Material, Integer> counts = countMaterials(corners);
183	        Material best = corners[0];
184	        int bestCount = -1;
185	        for (Map.Entry<Material, Integer> e : counts.entrySet()) {
186	            Material m = e.getKey();
187	            int c = e.getValue();
188	            if (c > bestCount
189	                    || (c == bestCount && m.impedance() > best.impedance())) {
190	                best = m;
191	                bestCount = c;
192	            }
193	        }
194	        return best;
195	    }
196	
197	    /**
198	     * Least-common material among those that are not primary; presence ties broken toward the
199	     * softer (lower-impedance) material.
200	     */
201	    private static @NotNull Material selectLeastCommon(@NotNull Material[] corners, @NotNull Material primary) {
202	        Map<Material, Integer> counts = countMaterials(corners);
203	        Material best = null;
204	        int bestCount = Integer.MAX_VALUE;
205	        for (Map.Entry<Material, Integer> e : counts.entrySet()) {
206	            Material m = e.getKey();
207	            if (m.equals(primary)) {
208	                continue;
209	            }
210	            int c = e.getValue();
211	            if (best == null
212	                    || c < bestCount
213	                    || (c == bestCount && m.impedance() < best.impedance())) {
214	                best = m;
215	                bestCount = c;
216	            }
217	        }
218	        if (best == null) {
219	            throw new IllegalStateException("heterogeneous octant must have a least-common material");
220	        }
221	        return best;
222	    }
223	
224	    private static @NotNull Map<Material, Integer> countMaterials(@NotNull Material[] corners) {
225	        Map<Material, Integer> counts = new HashMap<>();
226	        for (Material m : corners) {
227	            counts.merge(m, 1, Integer::sum);
228	        }
229	        return counts;
230	    }
