253	    public static @NotNull Vec3d combinePolar(@NotNull Vec3d[] childPolar, double[] childStiffWeight) {
254	        double sumWeight = 0.0;
255	        double x = 0.0, y = 0.0, z = 0.0;
256	        for (int i = 0; i < childPolar.length; i++) {
257	            double w = childStiffWeight[i];
