260	            y += p.y * w;
261	            z += p.z * w;
262	            sumWeight += w;
263	        }
264	        if (sumWeight == 0.0) {
265	            return Vec3d.ZERO;
266	        }
267	        return new Vec3d(x / sumWeight, y / sumWeight, z / sumWeight);
268	    }
