15	@Environment(EnvType.CLIENT)
16	public final class CaptureBuffer {
17	
18		private static final int MAX_CAPTURED_SEGMENTS = 16384;
19	
20		public static final CaptureBuffer INSTANCE = new CaptureBuffer(MAX_CAPTURED_SEGMENTS);
21	
22		public record CapturedRay(
23				Vec3d start,
24				Vec3d end,
25				int color,
26				int soundEventId,
27				/** Fibonacci/env-eval ray index within the sound event. */
28				int rayIndex,
29				int bounceIndex,
30				@Nullable Material material,
31				double reflectivity,
32				double transmission,
33				double power,
34				/** Impedance this bounce's reflectivity was computed against (the medium the ray was previously in). */
35				double priorImpedance,
36				/** Octree node size (in blocks) the boundary was resolved at; >1 means a coarse cached node. */
37				int branchSize,
38				@Nullable String materialLabel,
39				boolean terminated,
40				/** Impedance resolved at this boundary (the medium the ray is entering). */
41				double resolvedImpedance,
42				/** Alignment of the ray direction against the boundary's polar axis, in [-1, 1]. */
43				double polarAlignment,
44				/** Frustum/beam footprint size at this bounce, in blocks. */
45				double frustumSize,
46				/** Reason the bounce was left blank (e.g. "VACUUM"); null means NONE. */
47				@Nullable String blankReason,
48				/** Whether this bounce was resolved against exact block shape (true) or voxel occupancy (false). */
49				boolean shapeMode,
50				/** Whether the boundary's descriptor actually had a polarity vector — disambiguates
51				 *  {@code polarAlignment == 1.0} meaning "fully aligned" from "no polarity at all". */
52				boolean hasPolarity,
53				/** Growth was withheld this step (Task E double-cover / Task F envelopment guard). */
54				boolean growthDeferred,
55				/** Growth deferral resolved via a free/lossless parent-polarity graze (no bounce, no reverb hit). */
56				boolean freeRefraction,
57				/** Growth was withheld and this step reflected instead, because a look-ahead peek at
58				 *  the next same-size octant found a real boundary growth would have skipped over. */
59				boolean peekReflect
60		) {}
61	
62		private final int maxSegments;
63		private RingBuffer<CapturedRay> segments;
64		private int remaining;
65		/** When true, the next {@link #onSoundEvalStart} / {@link #offer} wipes prior segments. */
66		private boolean clearBeforeNextRecord;
67		private boolean truncationWarningPending;
68		private boolean truncationWarningFired;
69		private int version;
70	
71		CaptureBuffer(int maxSegments) {
72			this.maxSegments = maxSegments;
73			this.segments = new RingBuffer<>(maxSegments);
74		}
75	
76		/**
77		 * Arm capture for the next {@code events} sound evals. Does <em>not</em> clear existing
78		 * segments immediately — the wipe is deferred to the next record
79		 * ({@link #onSoundEvalStart} / first {@link #offer}) so re-arming cannot erase an unread
80		 * capture before Kapture runs.
81		 */
82		public synchronized void startCapture(int events) {
83			remaining = events;
84			clearBeforeNextRecord = true;
85			truncationWarningPending = false;
86			truncationWarningFired = false;
87			version++;
88		}
89	
90		public synchronized void stopCapture() {
91			remaining = 0;
92			version++;
93		}
94	
95		public synchronized boolean isCapturing() {
96			return remaining != 0;
97		}
98	
99		/** Clears prior segments once when an armed capture begins a sound eval (not on later evals). */
100		public synchronized void onSoundEvalStart() {
101			if (remaining != 0) {
102				clearSegmentsIfNeeded();
103			}
104		}
105	
106		public synchronized void onSoundEvalEnd() {
107			if (remaining > 0) {
108				remaining--;
109				version++;
110			}
111		}
112	
113		/**
114		 * Must be synchronized: {@code Engine.evalEnv} raycasts in parallel, and every debug segment
115		 * offer races into the same {@link RingBuffer}.
116		 */
117		public synchronized void offer(CapturedRay ray) {
118			if (remaining == 0) {
119				return;
120			}
121			clearSegmentsIfNeeded();
122			if (segments.size() == maxSegments) {
123				if (!truncationWarningFired) {
124					truncationWarningPending = true;
125					truncationWarningFired = true;
126				}
127			}
128			segments.offer(ray);
129			version++;
130		}
131	
132		private void clearSegmentsIfNeeded() {
133			if (!clearBeforeNextRecord) {
134				return;
135			}
136			segments = new RingBuffer<>(maxSegments);
137			clearBeforeNextRecord = false;
138			truncationWarningPending = false;
139			truncationWarningFired = false;
140			version++;
141		}
142	
143		public synchronized boolean consumeTruncationWarning() {
144			if (truncationWarningPending) {
145				truncationWarningPending = false;
146				return true;
147			}
148			return false;
149		}
150	
151		public synchronized List<CapturedRay> asCapturedList() {
152			return segments.asList();
153		}
154	
155		/** Distinct env-eval ray indexes present in the capture, in first-seen order. */
156		public synchronized List<Integer> capturedRayIndexes() {
157			Set<Integer> ordered = new LinkedHashSet<>();
158			for (CapturedRay ray : segments.asList()) {
159				ordered.add(ray.rayIndex());
160			}
161			return new ArrayList<>(ordered);
162		}
163	
164		public synchronized List<CapturedRay> segmentsForRayIndex(int rayIndex) {
165			List<CapturedRay> out = new ArrayList<>();
166			for (CapturedRay ray : segments.asList()) {
167				if (ray.rayIndex() == rayIndex) {
168					out.add(ray);
169				}
170			}
171			return out;
172		}
173	
174		public synchronized int version() {
175			return version;
176		}
177	
178		/** Total segments currently held (for debug HUD / dead-key diagnostics). */
179		public synchronized int size() {
180			return segments.size();
181		}
182	}
